export const PUNCTUATION_QUESTION_BANK: { q: string; o: string[]; a: number; e: string }[] = [
  { q: "Which sentence demonstrates the correct use of a comma with coordinating conjunctions joining independent clauses?", o: ["The test suite passed successfully, so we deployed the build to production.","The test suite passed successfully so, we deployed the build to production.","The test suite passed successfully; so we deployed the build to production.","The test suite passed successfully so we deployed the build to production."], a: 0, e: "Two independent clauses joined by a coordinating conjunction (FANBOYS) require a comma before the conjunction." },
  { q: "Choose the correct sentence featuring proper semicolon usage between independent clauses:", o: ["The database connection dropped; consequently, the transaction failed.","The database connection dropped consequently; the transaction failed.","The database connection dropped, consequently; the transaction failed.","The database connection dropped; consequently the transaction failed."], a: 0, e: "Conjunctive adverbs joining independent clauses require a semicolon before and a comma after." },
  { q: "Which sentence correctly uses a colon to introduce a list or explanation?", o: ["We need three core components for the project: a database, an API, and a frontend framework.","We need three core components for the project include: a database, an API, and a frontend framework.","We need: a database, an API, and a frontend framework for the project.","We need three core components for the project, namely: a database, an API, and a frontend framework."], a: 0, e: "A colon must follow an independent clause and can be used to introduce a list or explanation." },
  { q: "Identify the sentence with correct apostrophe usage for plural possessive nouns:", o: ["All the developers' workstations were upgraded yesterday.","All the developer's workstations were upgraded yesterday.","All the developers workstations were upgraded yesterday.","All the developers's workstations were upgraded yesterday."], a: 0, e: "For regular plural nouns ending in '-s', possession is indicated by placing the apostrophe after the 's'." },
  { q: "Which sentence demonstrates correct quotation mark placement with commas and periods in American English?", o: ["\"We have resolved the security vulnerability,\" announced the lead engineer.","\"We have resolved the security vulnerability\", announced the lead engineer.","\"We have resolved the security vulnerability\" announced the lead engineer.","\"We have resolved the security vulnerability.\" announced the lead engineer."], a: 0, e: "In American English, commas and periods go inside closing quotation marks." },
  { q: "Choose the sentence with correct hyphenation for compound modifiers before a noun:", o: ["We deployed a high-performance database cluster.","We deployed a high performance database cluster.","We deployed a highperformance database cluster.","We deployed a high, performance database cluster."], a: 0, e: "Compound adjectives preceding a noun they modify should be hyphenated to prevent ambiguity." },
  { q: "Identify the sentence correctly utilizing an em dash for dramatic interruption or emphasis:", o: ["Three modules—auth, billing, and logging—must be refactored before release.","Three modules, auth, billing, and logging—must be refactored before release.","Three modules—auth, billing, and logging, must be refactored before release.","Three modules: auth, billing, and logging—must be refactored before release."], a: 0, e: "Em dashes can be used in pairs to set off parenthetical info or appositives with strong emphasis." },
  { q: "Which sentence correctly punctuates introductory adverbial clauses or phrases?", o: ["After the build finished successfully, we pushed the changes to staging.","After the build finished successfully we pushed the changes to staging.","After the build finished successfully; we pushed the changes to staging.","After, the build finished successfully we pushed the changes to staging."], a: 0, e: "A dependent clause or long introductory phrase at the beginning of a sentence is followed by a comma." },
  { q: "Choose the correct sentence featuring proper apostrophe usage for joint possession vs. individual possession:", o: ["Alice and Bob's repository received numerous commits this week.","Alice's and Bob's repository received numerous commits this week (if shared).","Alices and Bobs repository received numerous commits this week.","Alice' and Bob' repository received numerous commits this week."], a: 0, e: "Joint possession is indicated by adding the possessive suffix only to the final name ('Alice and Bob's')." },
  { q: "Identify the sentence with correct comma placement in direct address:", o: ["Please review these pull request changes, Sarah, before merging.","Please review these pull request changes Sarah before merging.","Please review these pull request changes; Sarah, before merging.","Please review, these pull request changes Sarah, before merging."], a: 0, e: "Names or titles used in direct address must be set off with commas." },
  { q: "Which sentence demonstrates the correct use of parentheses for supplementary information?", o: ["The API rate limit (set at 1,000 requests per hour) protects our servers from abuse.","The API rate limit, set at 1,000 requests per hour (protects our servers from abuse).","The API rate limit set at (1,000 requests per hour) protects our servers from abuse.","The API rate limit (set at 1,000 requests per hour protects our servers from abuse)."], a: 0, e: "Parentheses enclose secondary or supplementary information that is structurally separate from the main sentence." },
  { q: "Choose the correct sentence using an apostrophe for contractions:", o: ["It's important that we verify the deployment logs.","Its important that we verify the deployment logs.","Its' important that we verify the deployment logs.","I'ts important that we verify the deployment logs."], a: 0, e: "'It's' with an apostrophe is the contraction for 'it is' or 'it has'." },
  { q: "Identify the correct possessive pronoun form (without an apostrophe):", o: ["The server cluster completed its scheduled backup cycle.","The server cluster completed it's scheduled backup cycle.","The server cluster completed its' scheduled backup cycle.","The server cluster completed it's' scheduled backup cycle."], a: 0, e: "The possessive pronoun 'its' does not contain an apostrophe." },
  { q: "Which sentence correctly applies punctuation in a series (Oxford comma usage)?", o: ["We need to test our database, API endpoints, and authentication middleware.","We need to test our database, API endpoints and authentication middleware.","We need to test our database; API endpoints, and authentication middleware.","We need to test our database: API endpoints, and authentication middleware."], a: 0, e: "The Oxford comma (placed before the conjunction in a series of three or more items) ensures clarity." },
  { q: "Choose the correct sentence showing proper semicolon usage to separate items in a complex list containing internal commas:", o: ["The conference featured speakers from Seattle, Washington; Austin, Texas; and Boston, Massachusetts.","The conference featured speakers from Seattle, Washington, Austin, Texas, and Boston, Massachusetts.","The conference featured speakers from Seattle, Washington: Austin, Texas: and Boston, Massachusetts.","The conference featured speakers from Seattle Washington; Austin Texas; and Boston Massachusetts."], a: 0, e: "Semicolons act as super-commas to separate list items that already contain internal commas." },
  { q: "Identify the sentence with correct punctuation for nonrestrictive (nonessential) clauses:", o: ["Our lead developer, who has ten years of experience, architected the system.","Our lead developer who has ten years of experience architected the system.","Our lead developer; who has ten years of experience; architected the system.","Our lead developer: who has ten years of experience: architected the system."], a: 0, e: "Nonrestrictive clauses provide supplementary detail and must be enclosed in commas." },
  { q: "Which sentence correctly punctuates restrictive (essential) clauses?", o: ["Developers who write comprehensive unit tests produce fewer bugs.","Developers, who write comprehensive unit tests, produce fewer bugs.","Developers; who write comprehensive unit tests; produce fewer bugs.","Developers—who write comprehensive unit tests—produce fewer bugs."], a: 0, e: "Restrictive clauses are necessary to identify the noun and are NOT set off by commas." },
  { q: "Choose the correct sentence featuring proper placement of a period with quotation marks in American English:", o: ["The project manager stated, \"We will finish the release by Friday.\"","The project manager stated, \"We will finish the release by Friday\".","The project manager stated \"We will finish the release by Friday.\"","The project manager stated: \"We will finish the release by Friday.\""], a: 0, e: "In American English, periods and commas are placed inside closing quotation marks." },
  { q: "Identify the sentence with correct hyphenation of age descriptors or compound units:", o: ["We hired a twenty-year-old software engineer.","We hired a twenty year old software engineer.","We hired a twenty-year old software engineer.","We hired a twenty year-old software engineer."], a: 0, e: "Compound adjective phrases expressing age before a noun are fully hyphenated." },
  { q: "Which sentence demonstrates the correct use of a slash or virgule?", o: ["Please review the terms and/or conditions before submitting.","Please review the terms and / or conditions before submitting.","Please review the terms and-or conditions before submitting.","Please review the terms, and/or conditions before submitting."], a: 0, e: "The slash ('and/or') is used without surrounding spaces to indicate mutually inclusive/exclusive options." },
  { q: "Choose the correct sentence featuring proper apostrophe usage for singular nouns ending in '-s':", o: ["Charles's research paper was published in a leading journal.","Charles' research paper was published in a leading journal (accepted variant).","Both options A and B are standard depending on style guides.","Charless research paper was published in a leading journal."], a: 2, e: "Both adding '-s' after the apostrophe (Charles's) and adding only the apostrophe (Charles') are accepted in various style manuals." },
  { q: "Identify the sentence with correct comma usage in dates and geographical locations:", o: ["The conference was held in Trivandrum, Kerala, on July 14, 2026.","The conference was held in Trivandrum Kerala on July 14 2026.","The conference was held in Trivandrum, Kerala on July 14 2026.","The conference was held in Trivandrum Kerala, on July 14, 2026."], a: 0, e: "Commas separate city from state/region, and separate the day, month, year (plus a closing comma after the year in mid-sentence)." },
  { q: "Which sentence correctly punctuates coordinate adjectives preceding a noun?", o: ["The application featured a sleek, responsive interface.","The application featured a sleek and responsive interface (or sleek responsive interface without comma if cumulative).","The application featured a sleek responsive interface.","The application featured a sleek, responsive, interface."], a: 0, e: "Coordinate adjectives (adjectives that equally modify the noun and can be joined by 'and') are separated by commas." },
  { q: "Choose the correct sentence utilizing an apostrophe for plural lowercase letters or numbers (to avoid confusion):", o: ["Make sure to dot your i's and cross your t's.","Make sure to dot your is and cross your ts.","Make sure to dot your i’s and cross your t’s.","Make sure to dot your i'es and cross your t'es."], a: 0, e: "Plurals of lowercase letters, numbers, and abbreviations take an apostrophe with 's' for clarity." },
  { q: "Identify the sentence with correct quotation marks for titles of articles or short works:", o: ["Have you read the article \"Optimizing Cloudflare Workers\" on the blog?","Have you read the article *Optimizing Cloudflare Workers* on the blog?","Have you read the article _Optimizing Cloudflare Workers_ on the blog?","Have you read the article Optimizing Cloudflare Workers on the blog?"], a: 0, e: "Titles of shorter works (articles, essays, book chapters) are enclosed in quotation marks." },
  { q: "Which sentence correctly punctuates dialogue tags and quotation marks?", o: ["\"We have fixed the bug,\" said the developer, \"so you can test the staging build.\"","\"We have fixed the bug\" said the developer, \"so you can test the staging build.\"","\"We have fixed the bug,\" said the developer. \"So you can test the staging build.\"","Both options A and C are grammatically correct depending on sentence flow."], a: 3, e: "Dialogue interrupted by a speech tag uses commas correctly, while separate sentences close with periods." },
  { q: "Choose the correct sentence demonstrating proper hyphenation in prefix attachments:", o: ["We need to re-evaluate our database indexing strategy.","We need to reevaluate our database indexing strategy (also accepted in many modern guides).","Both options A and B are widely accepted in contemporary technical writing.","We need to re evaluate our database indexing strategy."], a: 2, e: "While traditional rules hyphenate words starting with re- to prevent misreading (re-evaluate), modern dictionaries frequently accept closed forms (reevaluate)." },
  { q: "Identify the sentence with correct comma placement with introductory transitional words:", o: ["Furthermore, we must optimize our API response times before launch.","Furthermore we must optimize our API response times before launch.","Furthermore; we must optimize our API response times before launch.","Furthermore—we must optimize our API response times before launch."], a: 0, e: "Introductory transitional words (furthermore, however, moreover) are followed by a comma." },
  { q: "Which sentence correctly uses an ellipsis to indicate omitted text within a quotation?", o: ["\"We plan to upgrade our infrastructure ... by the end of next quarter.\"","\"We plan to upgrade our infrastructure ... by the end of next quarter.\" (with spaces around ellipsis)","\"We plan to upgrade our infrastructure... by the end of next quarter.\"","All of the above depending on style manual standards (APA, MLA, Chicago)."], a: 3, e: "Different style guides prescribe specific spacing and punctuation rules for ellipses representing omissions." },
  { q: "Choose the correct sentence featuring proper punctuation of parenthetical dashes:", o: ["The three core technologies—Next.js, Cloudflare D1, and Backblaze B2—power our web application.","The three core technologies, Next.js, Cloudflare D1, and Backblaze B2—power our web application.","The three core technologies—Next.js, Cloudflare D1, and Backblaze B2, power our web application.","The three core technologies: Next.js, Cloudflare D1, and Backblaze B2—power our web application."], a: 0, e: "Paired em dashes enclose parenthetical phrases without needing additional commas." },
  { q: "Identify the sentence with correct capitalization and punctuation of a complete sentence following a colon:", o: ["Remember this rule: Always back up your database before running migrations.","Remember this rule: always back up your database before running migrations.","Remember this rule, Always back up your database before running migrations.","Remember this rule; Always back up your database before running migrations."], a: 0, e: "When a colon introduces a complete independent clause, capitalizing the first word after the colon is standard in many American style guides." },
  { q: "Which sentence correctly avoids a comma splice?", o: ["The server crashed during peak hours, and we had to reboot the gateway.","The server crashed during peak hours, we had to reboot the gateway.","The server crashed during peak hours we had to reboot the gateway.","The server crashed during peak hours; and we had to reboot the gateway."], a: 0, e: "Joining two independent clauses with only a comma creates a comma splice; a coordinating conjunction must be added after the comma." },
  { q: "Choose the correct sentence featuring proper hyphenation for compound numbers (twenty-one to ninety-nine):", o: ["We successfully resolved forty-two bug tickets this sprint.","We successfully resolved forty two bug tickets this sprint.","We successfully resolved forty_two bug tickets this sprint.","We successfully resolved forty.two bug tickets this sprint."], a: 0, e: "Compound numbers from twenty-one to ninety-nine are hyphenated." },
  { q: "Identify the sentence with correct punctuation for an absolute phrase:", o: ["Their server migration completed ahead of schedule, the engineering team took a well-deserved break.","Their server migration completed ahead of schedule; the engineering team took a well-deserved break.","Their server migration completed ahead of schedule and the engineering team took a well-deserved break.","Their server migration completed ahead of schedule—the engineering team took a well-deserved break."], a: 0, e: "An absolute phrase modifying the entire sentence is set off with a comma." },
  { q: "Which sentence demonstrates the correct use of question marks with direct vs. indirect questions?", o: ["She asked whether the migration script had finished executing.","She asked whether the migration script had finished executing?","Did she ask whether the migration script had finished executing.","She asked: \"Had the migration script finished executing?\""], a: 0, e: "Indirect questions do not take question marks at the end of the sentence." },
  { q: "Choose the correct sentence featuring proper punctuation of exclamation marks within quotation marks:", o: ["\"We deployed successfully!\" shouted the lead engineer.","\"We deployed successfully\"! shouted the lead engineer.","\"We deployed successfully! shouted the lead engineer.\"","\"We deployed successfully! shouted the lead engineer\"!"], a: 0, e: "Exclamation points go inside the quotation marks if they apply directly to the quoted quotation." },
  { q: "Identify the sentence with correct punctuation of a sentence-ending period with parentheses:", o: ["Please refer to the documentation for further details (see Appendix A).","Please refer to the documentation for further details (see Appendix A.)","Please refer to the documentation for further details (see Appendix A)..","Please refer to the documentation for further details. (see Appendix A)"], a: 0, e: "When parenthetical matter falls at the end of a sentence, the period goes outside the closing parenthesis." },
  { q: "Which sentence correctly uses an apostrophe for omitted letters in years or decades?", o: ["She fondly remembered her college days in the '90s.","She fondly remembered her college days in the 90's (also common).","She fondly remembered her college days in the '90's.","Both options A and B are widely accepted."], a: 3, e: "Indicating decades as '90s or 90's are both accepted conventions in modern publishing." },
  { q: "Choose the correct sentence featuring proper comma placement with interjections:", o: ["Oh, I understand how the caching layer handles invalidation now.","Oh I understand how the caching layer handles invalidation now.","Oh; I understand how the caching layer handles invalidation now.","Oh—I understand how the caching layer handles invalidation now."], a: 0, e: "Mild interjections at the beginning of a sentence are set off with a comma." },
  { q: "Identify the sentence with correct punctuation of an introductory participial phrase:", o: ["Reviewing the error logs, the developer identified the memory leak.","Reviewing the error logs the developer identified the memory leak.","Reviewing the error logs; the developer identified the memory leak.","Reviewing, the error logs the developer identified the memory leak."], a: 0, e: "An introductory participial phrase modifying the subject must be followed by a comma." },
  { q: "Which sentence correctly demonstrates the distinction between an en dash and a hyphen?", o: ["Please read pages 45–60 of the system architecture manual.","Please read pages 45-60 of the system architecture manual.","Please read pages 45 to 60 of the system architecture manual.","Both options A and C are standard."], a: 3, e: "An en dash (–) is standard for number ranges (pages 45–60), while hyphens connect compound words." },
  { q: "Choose the correct sentence featuring proper punctuation in a split quotation with a speech tag:", o: ["\"We can merge the branch,\" explained the reviewer, \"once all tests pass.\"","\"We can merge the branch\" explained the reviewer, \"once all tests pass.\"","\"We can merge the branch\", explained the reviewer, \"once all tests pass.\"","\"We can merge the branch;\" explained the reviewer \"once all tests pass.\""], a: 0, e: "When a speech tag splits a single quoted sentence, the tag is set off by commas, and the second half of the quote starts with a lowercase letter." },
  { q: "Identify the sentence with correct punctuation of appositives:", o: ["Our lead database administrator, Rajesh, optimized the PostgreSQL queries.","Our lead database administrator Rajesh, optimized the PostgreSQL queries.","Our lead database administrator, Rajesh optimized the PostgreSQL queries.","Our lead database administrator Rajesh optimized the PostgreSQL queries."], a: 0, e: "Nonessential appositives (identifying nouns that can be removed without altering the core meaning) are enclosed in commas." },
  { q: "Which sentence correctly demonstrates the use of a colon after a salutation in formal business correspondence?", o: ["Dear Hiring Manager:","Dear Hiring Manager,","Dear Hiring Manager;","Dear Hiring Manager—"], a: 0, e: "In formal American business letters, a colon follows the salutation (while a comma is standard in British English)." },
  { q: "Choose the correct sentence featuring proper comma usage with contrasting expressions ('not... but'):", o: ["The failure resulted from a network timeout, not a database deadlock.","The failure resulted from a network timeout not a database deadlock.","The failure resulted from a network timeout; not a database deadlock.","The failure resulted from a network timeout—not a database deadlock."], a: 0, e: "Contrasting elements introduced by 'not' are set off with a comma." },
  { q: "Identify the sentence with correct punctuation of a conditional clause preceding the main clause:", o: ["If the build passes, we will release the update to production.","If the build passes we will release the update to production.","If the build passes; we will release the update to production.","If the build passes—we will release the update to production."], a: 0, e: "A conditional dependent clause preceding the main clause requires a comma after it." },
  { q: "Which sentence correctly demonstrates proper punctuation of a compound sentence without a conjunction (run-on sentence correction)?", o: ["The bug was critical; we patched it immediately.","The bug was critical, we patched it immediately.","The bug was critical we patched it immediately.","The bug was critical, and we patched it immediately."], a: 0, e: "Two closely related independent clauses can be joined directly with a semicolon when no coordinating conjunction is used." },
  { q: "Choose the correct sentence featuring proper punctuation for titles of books or full-length works:", o: ["Have you read *Clean Code* by Robert C. Martin?","Have you read \"Clean Code\" by Robert C. Martin?","Have you read _Clean Code_ by Robert C. Martin?","Both options A and C are standard typographic practices for book titles."], a: 3, e: "Full-length works like books are italicized or underlined." },
  { q: "Identify the sentence with correct comma placement with geographical addresses in running text:", o: ["She relocated from 42 Park Avenue, New York, NY, to San Francisco, California.","She relocated from 42 Park Avenue New York NY to San Francisco California.","She relocated from 42 Park Avenue, New York NY to San Francisco California.","She relocated from 42 Park Avenue New York, NY, to San Francisco, California."], a: 0, e: "Street address, city, state, and closing state references require internal commas separating each element in running text." },
  { q: "Which sentence demonstrates the correct use of quotation marks for scare quotes or irony?", o: ["His \"expert\" debugging skills consisted of restarting the server and hoping for the best.","His expert debugging skills consisted of restarting the server and hoping for the best.","His *expert* debugging skills consisted of restarting the server and hoping for the best.","His _expert_ debugging skills consisted of restarting the server and hoping for the best."], a: 0, e: "Quotation marks can be used to indicate irony, skepticism, or scare quotes around a term used in a nonstandard way." },
  { q: "Which sentence demonstrates the correct use of square brackets for editorial insertions within quoted material?", o: ["\"[The lead developer] confirmed that the bug has been patched,\" stated the project manager.","\"The lead developer [confirmed] that the bug has been patched,\" stated the project manager.","\"The lead developer confirmed that the bug has been patched [sic],\" stated the project manager.","Both options A and C are correct uses of square brackets."], a: 3, e: "Square brackets are used to insert explanatory words or clarifications into quotes (Option A) or to note errors using [sic] (Option C)." },
  { q: "Choose the correct sentence featuring proper punctuation with quotation marks and question marks when the question applies to the entire sentence:", o: ["Have you read the article titled \"Optimizing Cloudflare Workers\"?","Have you read the article titled \"Optimizing Cloudflare Workers?\"","Did the engineer ask, \"Have we resolved all security vulnerabilities?\"","Both options A and C are grammatically correct."], a: 3, e: "When a question mark applies to the whole sentence containing a quoted title, it goes outside (Option A); when the quote itself is a question, it goes inside (Option C)." },
  { q: "Which sentence correctly punctuates a list introduced by a colon following an incomplete independent clause?", o: ["The required tools include: Python, Git, and Docker.","The required tools include Python, Git, and Docker.","The required tools: Python, Git, and Docker.","The required tools include, Python, Git, and Docker."], a: 1, e: "A colon should not separate a verb from its direct object or complement; a colon must follow a complete independent clause." },
  { q: "Identify the sentence with correct apostrophe usage for plural words or numbers used as nouns:", o: ["During the 1990s, web development underwent massive architectural transformations.","During the 1990's, web development underwent massive architectural transformations.","During the 1990s', web development underwent massive architectural transformations.","During the 1990 es, web development underwent massive architectural transformations."], a: 0, e: "Decades expressed in figures take an 's' without an apostrophe (1990s)." },
  { q: "Which sentence demonstrates the correct use of a comma to separate coordinate clauses?", o: ["The staging build passed all automated tests, and the deployment script executed without errors.","The staging build passed all automated tests and the deployment script executed without errors.","The staging build passed all automated tests; and the deployment script executed without errors.","The staging build passed all automated tests, and, the deployment script executed without errors."], a: 0, e: "Two independent clauses joined by coordinating conjunctions (FANBOYS) require a comma before the conjunction." },
  { q: "Choose the sentence with correct hyphenation for compound adjectives following the noun:", o: ["Our server cluster is high-performance.","Our server cluster is high performance.","Our server cluster is high-performance.","Both options A and C correctly reflect predicate adjective style rules in some guides."], a: 1, e: "When compound adjectives follow the noun they modify (predicate position), they are typically not hyphenated, though some technical style guides permit it." },
  { q: "Identify the sentence correctly utilizing commas with nonessential appositives:", o: ["Our database administrator, Arun, optimized the D1 database queries.","Our database administrator Arun, optimized the D1 database queries.","Our database administrator, Arun optimized the D1 database queries.","Our database administrator Arun optimized the D1 database queries."], a: 0, e: "Nonessential appositives providing extra naming detail are enclosed in commas." },
  { q: "Which sentence correctly punctuates an introductory participial phrase?", o: ["Having completed the code review, the engineer pushed the changes to production.","Having completed the code review the engineer pushed the changes to production.","Having completed the code review; the engineer pushed the changes to production.","Having completed, the code review the engineer pushed the changes to production."], a: 0, e: "An introductory participial phrase modifying the subject requires a comma after it." },
  { q: "Choose the correct sentence featuring proper punctuation for a series with internal complexity:", o: ["The conference included speakers from Trivandrum, Kerala; Bengaluru, Karnataka; and Mumbai, Maharashtra.","The conference included speakers from Trivandrum, Kerala, Bengaluru, Karnataka, and Mumbai, Maharashtra.","The conference included speakers from Trivandrum Kerala: Bengaluru Karnataka: and Mumbai Maharashtra.","The conference included speakers from Trivandrum-Kerala, Bengaluru-Karnataka, and Mumbai-Maharashtra."], a: 0, e: "Semicolons act as super-commas to separate complex list items containing internal commas." },
  { q: "Identify the sentence with correct comma placement in direct address:", o: ["Can you verify these database logs, Vaibhav, before we log off?","Can you verify these database logs Vaibhav before we log off?","Can you verify these database logs; Vaibhav, before we log off?","Can you verify, these database logs Vaibhav, before we log off?"], a: 0, e: "Names or titles used in direct address are set off with commas." },
  { q: "Which sentence demonstrates the correct use of parentheses for numbered list items within running text?", o: ["The project requires (1) database optimization, (2) API caching, and (3) frontend minification.","The project requires 1) database optimization, 2) API caching, and 3) frontend minification.","Both options A and C are acceptable in various technical writing style manuals.","The project requires (1 database optimization), (2 API caching), and (3 frontend minification."], a: 2, e: "Enclosing numbers in parentheses or using single closing parentheses for inline list items are both standard formatting practices." },
  { q: "Choose the correct sentence using an apostrophe for plural nouns that do not end in '-s':", o: ["The children's playground was renovated last month.","The childrens' playground was renovated last month.","The childrens playground was renovated last month.","The children's' playground was renovated last month."], a: 0, e: "Plural nouns not ending in '-s' (like children, men, women) form the possessive by adding an apostrophe followed by 's'." },
  { q: "Identify the correct possessive pronoun form (without an apostrophe):", o: ["Each microservice maintains its own independent database schema.","Each microservice maintains it's own independent database schema.","Each microservice maintains its' own independent database schema.","Each microservice maintains it's' own independent database schema."], a: 0, e: "The possessive pronoun 'its' does not take an apostrophe." },
  { q: "Which sentence correctly applies the Oxford comma in a compound series?", o: ["We need to configure Next.js, Cloudflare D1, and Backblaze B2.","We need to configure Next.js, Cloudflare D1 and Backblaze B2.","We need to configure Next.js; Cloudflare D1, and Backblaze B2.","We need to configure Next.js: Cloudflare D1, and Backblaze B2."], a: 0, e: "The Oxford comma before the final conjunction prevents ambiguity in series." },
  { q: "Choose the correct sentence showing proper semicolon usage between independent clauses without a conjunctive adverb:", o: ["The server load was exceptionally high; engineers initiated additional worker instances.","The server load was exceptionally high, engineers initiated additional worker instances.","The server load was exceptionally high engineers initiated additional worker instances.","The server load was exceptionally high: and engineers initiated additional worker instances."], a: 0, e: "Closely related independent clauses can be joined directly by a semicolon without a coordinating conjunction." },
  { q: "Identify the sentence with correct punctuation for restrictive clauses:", o: ["Engineers who write clean code make fewer deployment errors.","Engineers, who write clean code, make fewer deployment errors.","Engineers; who write clean code; make fewer deployment errors.","Engineers—who write clean code—make fewer deployment errors."], a: 0, e: "Restrictive clauses are essential to the noun's identity and are not set off by commas." },
  { q: "Which sentence correctly punctuates nonrestrictive clauses?", o: ["Our lead DevOps engineer, who automated our CI/CD pipeline, received an award.","Our lead DevOps engineer who automated our CI/CD pipeline received an award.","Our lead DevOps engineer; who automated our CI/CD pipeline; received an award.","Our lead DevOps engineer: who automated our CI/CD pipeline: received an award."], a: 0, e: "Nonrestrictive clauses provide supplementary information and are enclosed in commas." },
  { q: "Choose the correct sentence featuring proper placement of a comma with quotation marks in American English:", o: ["\"We have optimized the database queries,\" stated the backend engineer.","\"We have optimized the database queries\", stated the backend engineer.","\"We have optimized the database queries\" stated the backend engineer.","\"We have optimized the database queries.\" stated the backend engineer."], a: 0, e: "In American English, commas always go inside closing quotation marks." },
  { q: "Identify the sentence with correct hyphenation of compound words or fractions:", o: ["Two-thirds of the survey respondents reported positive user experiences.","Two thirds of the survey respondents reported positive user experiences.","Two-thirds of the survey respondents reported positive, user experiences.","Two thirds of the survey respondents reported positive-user experiences."], a: 0, e: "Fractions used as adjectives or nouns are hyphenated (two-thirds)." },
  { q: "Which sentence demonstrates the correct use of an em dash for emphasis or sudden break in thought?", o: ["We finished the entire sprint backlog—ahead of schedule.","We finished the entire sprint backlog, ahead of schedule—.","We finished the entire sprint backlog: ahead of schedule—","We finished the entire sprint backlog; ahead of schedule—"], a: 0, e: "An em dash can be used to emphasize a concluding point or a sudden break." },
  { q: "Choose the correct sentence featuring proper apostrophe usage for plural family names ending in '-s' (e.g., the Ahuja family):", o: ["The Ahujas' residence is located in Trivandrum, Kerala.","The Ahuja's residence is located in Trivandrum, Kerala.","The Ahujases residence is located in Trivandrum, Kerala.","The Ahujas's residence is located in Trivandrum, Kerala."], a: 0, e: "To show plural possession for family names ending in '-s', add an apostrophe after the '-s' (the Ahujas')." },
  { q: "Identify the sentence with correct comma usage in numbers (thousands separators):", o: ["The application processed 1,500,000 requests during peak hours.","The application processed 1.500.000 requests during peak hours.","The application processed 1 500 000 requests during peak hours.","The application processed 1,50,00,00 requests during peak hours."], a: 0, e: "Standard international English numbering separates thousands with commas (though South Asian numbering uses lakhs/crores)." },
  { q: "Which sentence correctly punctuates cumulative adjectives preceding a noun?", o: ["We stored backup files on a secure external hard drive.","We stored backup files on a secure, external, hard drive.","We stored backup files on a secure and external and hard drive.","We stored backup files on a secure, external hard drive."], a: 0, e: "Cumulative adjectives build upon each other and do not require commas between them because they cannot be joined by 'and'." },
  { q: "Choose the correct sentence utilizing an apostrophe for omitted letters in informal contractions:", o: ["Let's review the deployment pipeline configuration.","Lets review the deployment pipeline configuration.","Let's' review the deployment pipeline configuration.","Lets' review the deployment pipeline configuration."], a: 0, e: "'Let's' is the standard contraction for 'let us'." },
  { q: "Identify the sentence with correct quotation marks for titles of book chapters or poems:", o: ["Chapter 3 is titled \"Advanced Database Architecture\".","Chapter 3 is titled *Advanced Database Architecture*.","Chapter 3 is titled _Advanced Database Architecture_.","Chapter 3 is titled Advanced Database Architecture."], a: 0, e: "Titles of book chapters, articles, and short poems are enclosed in quotation marks." },
  { q: "Which sentence correctly punctuates dialogue with an interrupting speech tag?", o: ["\"We have finished testing,\" reported the QA lead, \"so we can proceed with release.\"","\"We have finished testing\" reported the QA lead, \"so we can proceed with release.\"","\"We have finished testing\", reported the QA lead, \"so we can proceed with release.\"","\"We have finished testing;\" reported the QA lead \"so we can proceed with release.\""], a: 0, e: "An interrupting speech tag is enclosed by commas, with the second part of the quote starting in lowercase." },
  { q: "Choose the correct sentence demonstrating proper punctuation with compound modifiers involving numbers:", o: ["We scheduled a three-day sprint planning session.","We scheduled a three day sprint planning session.","We scheduled a three-days sprint planning session.","We scheduled a three days' sprint planning session."], a: 0, e: "Compound adjective phrases with numbers and singular nouns before a noun are hyphenated ('three-day')." },
  { q: "Identify the sentence with correct comma placement after introductory prepositional phrases:", o: ["During the morning standup, the team reviewed individual task statuses.","During the morning standup the team reviewed individual task statuses.","During the morning standup; the team reviewed individual task statuses.","During, the morning standup the team reviewed individual task statuses."], a: 0, e: "Long introductory prepositional phrases (or multiple short ones) are followed by a comma." },
  { q: "Which sentence correctly uses an ellipsis to show hesitation or trailing thought in dialogue?", o: ["\"I thought we deployed the patch... but apparently not.\"","\"I thought we deployed the patch...but apparently not.\"","\"I thought we deployed the patch...  but apparently not.\"","All of the above are acceptable typographic variants."], a: 3, e: "Spacing around ellipses for trailing thoughts in fiction/dialogue varies across style manuals." },
  { q: "Choose the correct sentence featuring proper punctuation of parenthetical em dashes enclosing an appositive:", o: ["Our primary cloud providers—Backblaze B2 and Cloudflare—ensure high availability.","Our primary cloud providers, Backblaze B2 and Cloudflare—ensure high availability.","Our primary cloud providers—Backblaze B2 and Cloudflare, ensure high availability.","Our primary cloud providers: Backblaze B2 and Cloudflare—ensure high availability."], a: 0, e: "Paired em dashes enclose parenthetical interruptions seamlessly." },
  { q: "Identify the sentence with correct capitalization and punctuation after a colon introducing a subtitle:", o: ["Shoppers Ocean: A Global Entertainment Web Application","Shoppers Ocean: a global entertainment web application","Shoppers Ocean—A global entertainment web application","Shoppers Ocean, A Global Entertainment Web Application"], a: 0, e: "Main titles and subtitles separated by colons capitalize the first word of the subtitle." },
  { q: "Which sentence correctly avoids a comma splice by using a coordinating conjunction?", o: ["The database migration completed successfully, and all verification tests passed.","The database migration completed successfully, all verification tests passed.","The database migration completed successfully all verification tests passed.","The database migration completed successfully; and all verification tests passed."], a: 0, e: "Commas alone cannot join independent clauses; adding 'and' resolves the comma splice." },
  { q: "Choose the correct sentence featuring proper hyphenation for prefixes like 'anti-' or 'co-' before vowels:", o: ["We need to implement anti-malware software on all workstations.","We need to implement antimalware software on all workstations (also common).","Both options A and B are widely accepted in modern publishing.","We need to implement anti malware software on all workstations."], a: 2, e: "Modern dictionaries frequently accept closed forms for common prefixes (antimalware), while traditional styles retained hyphens (anti-malware)." },
  { q: "Identify the sentence with correct punctuation for an absolute phrase at the end of a sentence:", o: ["The development team pushed the update, their morale boosted by the successful test run.","The development team pushed the update; their morale boosted by the successful test run.","The development team pushed the update and their morale boosted by the successful test run.","The development team pushed the update—their morale boosted by the successful test run."], a: 0, e: "Absolute phrases modifying a clause are separated by a comma." },
  { q: "Which sentence demonstrates the correct use of a question mark with a polite request structured as a question?", o: ["Would you please review this pull request when you have a moment?","Would you please review this pull request when you have a moment.","Would you please review this pull request when you have a moment!","Would you please review this pull request when you have a moment;?"], a: 0, e: "Direct questions formulated as polite requests still require a question mark." },
  { q: "Choose the correct sentence featuring proper punctuation of question marks within quotation marks:", o: ["Did the client ask, \"When will the new dashboard feature be deployed?\"","Did the client ask, \"When will the new dashboard feature be deployed\"?","Did the client ask, \"When will the new dashboard feature be deployed?\"?","Did the client ask? \"When will the new dashboard feature be deployed?\""], a: 0, e: "When the entire sentence is a question containing a quoted question, a single question mark goes inside the quotation marks, and no final question mark is added outside." },
  { q: "Identify the sentence with correct punctuation when parentheses occur at the end of a sentence containing a full independent statement inside:", o: ["The database migration was completed overnight. (See Appendix B for detailed logs.)","The database migration was completed overnight (See Appendix B for detailed logs).","The database migration was completed overnight. (See Appendix B for detailed logs)","The database migration was completed overnight (See Appendix B for detailed logs.)"], a: 0, e: "When parenthetical material forms a complete independent sentence standing alone outside the main text, its period goes inside the closing parenthesis." },
  { q: "Which sentence correctly uses an apostrophe to indicate omitted letters in colloquial speech?", o: ["\"Rock 'n' roll\" is often abbreviated with apostrophes framing the dropped letters.","\"Rock n roll\" requires no apostrophes.","\"Rock'n'roll\" uses single quotes.","None of the above."], a: 0, e: "Apostrophes replace omitted letters in shortened words like 'n' (and) or 'tis." },
  { q: "Choose the correct sentence featuring proper comma placement with contrasting introductory phrases:", o: ["Unlike the legacy system, the new architecture handles high concurrency effortlessly.","Unlike the legacy system the new architecture handles high concurrency effortlessly.","Unlike the legacy system; the new architecture handles high concurrency effortlessly.","Unlike, the legacy system the new architecture handles high concurrency effortlessly."], a: 0, e: "Introductory contrasting prepositional phrases or clauses are followed by a comma." },
  { q: "Identify the sentence with correct punctuation of an introductory adjective phrase:", o: ["Confident in their test results, the developers deployed the update.","Confident in their test results the developers deployed the update.","Confident in their test results; the developers deployed the update.","Confident, in their test results the developers deployed the update."], a: 0, e: "Introductory adjective phrases modifying the subject are followed by a comma." },
  { q: "Which sentence correctly demonstrates the use of an en dash for sports scores or competitive results?", o: ["Our team won the championship match 4–2.","Our team won the championship match 4-2.","Our team won the championship match 4 to 2.","Both options A and C are standard."], a: 3, e: "An en dash (–) is standard in publishing for scores, results, and directional ranges." },
  { q: "Choose the correct sentence featuring proper punctuation when a quotation is integrated into the syntax of your own sentence without a comma:", o: ["The lead architect noted that \"the caching layer significantly reduces database load.\"","The lead architect noted that, \"the caching layer significantly reduces database load.\"","The lead architect noted that: \"the caching layer significantly reduces database load.\"","The lead architect noted that—\"the caching layer significantly reduces database load.\""], a: 0, e: "When a quotation flows syntactically as part of your sentence following 'that', no comma is required before the quote." },
  { q: "Identify the sentence with correct punctuation of essential vs. nonessential geographical modifiers:", o: ["Our office in Trivandrum, Kerala, coordinates all backend deployments.","Our office in Trivandrum Kerala coordinates all backend deployments.","Our office in Trivandrum; Kerala; coordinates all backend deployments.","Our office in Trivandrum: Kerala coordinates all backend deployments."], a: 0, e: "State or country names following a city name in running text are enclosed by commas." },
  { q: "Which sentence correctly demonstrates the use of a colon after an independent clause introducing a formal resolution or quote?", o: ["The committee reached a unanimous conclusion: Quality assurance is mandatory before release.","The committee reached a unanimous conclusion, Quality assurance is mandatory before release.","The committee reached a unanimous conclusion; Quality assurance is mandatory before release.","The committee reached a unanimous conclusion—Quality assurance is mandatory before release."], a: 0, e: "A colon correctly introduces a formal statement or quotation following a full independent clause." },
  { q: "Choose the correct sentence featuring proper comma usage with direct quotations and attribution splits:", o: ["\"We must ensure zero downtime,\" explained the DevOps engineer, \"during the server migration.\"","\"We must ensure zero downtime\" explained the DevOps engineer, \"during the server migration.\"","\"We must ensure zero downtime\", explained the DevOps engineer \"during the server migration.\"","\"We must ensure zero downtime;\" explained the DevOps engineer \"during the server migration.\""], a: 0, e: "Split dialogue quotes require commas after the first quote segment and after the speech tag." },
  { q: "Identify the sentence with correct punctuation of a conditional clause following the main clause (no comma needed):", o: ["We will deploy the patch immediately if the staging build passes all tests.","We will deploy the patch immediately, if the staging build passes all tests.","We will deploy the patch immediately; if the staging build passes all tests.","We will deploy the patch immediately—if the staging build passes all tests."], a: 0, e: "When the conditional dependent clause follows the main clause, no comma is typically required." },
  { q: "Which sentence correctly demonstrates proper punctuation of compound sentences joined by conjunctive adverbs?", o: ["The build completed successfully; therefore, we initiated the deployment sequence.","The build completed successfully, therefore, we initiated the deployment sequence.","The build completed successfully therefore; we initiated the deployment sequence.","The build completed successfully, therefore we initiated the deployment sequence."], a: 0, e: "Conjunctive adverbs joining independent clauses require a semicolon before and a comma after." },
  { q: "Choose the correct sentence featuring proper punctuation for titles of computer software or applications:", o: ["We use Next.js for our frontend web application architecture.","We use \"Next.js\" for our frontend web application architecture.","We use *Next.js* for our frontend web application architecture.","We use _Next.js_ for our frontend web application architecture."], a: 0, e: "Proprietary software, operating systems, and application frameworks (like Next.js) are written in plain roman text without quotation marks or italics." },
  { q: "Identify the sentence with correct comma placement with degrees and professional titles after names:", o: ["Dr. Ananya Sharma, Ph.D., authored the comprehensive cryptography whitepaper.","Dr. Ananya Sharma Ph.D. authored the comprehensive cryptography whitepaper.","Dr. Ananya Sharma, Ph.D authored the comprehensive cryptography whitepaper.","Dr. Ananya Sharma Ph.D., authored the comprehensive cryptography whitepaper."], a: 0, e: "Professional degrees and titles following a person's name in running text are set off by commas before and after." },
  { q: "Which sentence demonstrates the correct use of quotation marks for coined terms or technical jargon introduced for the first time?", o: ["The technique of pushing code changes via AI prompts is known as \"prompt-driven development.\"","The technique of pushing code changes via AI prompts is known as prompt-driven development.","The technique of pushing code changes via AI prompts is known as *prompt-driven development*.","Both options A and C are accepted depending on editorial style."], a: 3, e: "New technical terms, jargon, or coined expressions can be introduced using quotation marks or italics on first reference." },
];
